function slugify(text) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

const tutorialCategories = [
  ...new Set(sampleContent.tutorials.map((item) => item.category)),
].map((name) => ({ collection: "tutorialCategories", item: { name, slug: slugify(name), published: true } }));
const faqCategories = [
  ...new Set(sampleContent.faqs.map((item) => item.category)),
].map((name) => ({ collection: "faqCategories", item: { name, slug: slugify(name), published: true } }));

export const starterEntries = [
  ...sampleContent.tutorials.map((item) => ({ collection: "tutorials", item })),
  ...sampleContent.updates.map((item) => ({ collection: "updates", item })),
  ...sampleContent.faqs.map((item) => ({ collection: "faqs", item })),
  ...tutorialCategories,
  ...faqCategories,
].map(({ collection, item }) => {
  const { id: ignored, ...fields } = item;
  return {
    collection,
    id: item.slug || item.id || slugify(item.question || item.name),
    item: fields,
  };
});
